Add three evaluation functions to `evaluate.py`. Each uses Claude as a judge to score the chatbot's answer.

```python
def score_faithfulness(context, answer):
    """Does the answer stick to the context? (0.0 = hallucination, 1.0 = faithful)"""
    response = client.messages.create(
        model="claude-sonnet-4-20250514",
        max_tokens=100,
        messages=[{
            "role": "user",
            "content": f"""Score 0.0 to 1.0: Is this answer supported by the context?
            1.0 = fully supported, 0.0 = completely made up.
            Context: {context}
            Answer: {answer}
            Reply with ONLY a JSON object: {{"score": <number>}}"""
        }],
    )
    try:
        return json.loads(response.content[0].text)["score"]
    except:
        return 0.5


def score_relevancy(question, answer):
    """Does the answer address the question? (0.0 = off-topic, 1.0 = perfect)"""
    response = client.messages.create(
        model="claude-sonnet-4-20250514",
        max_tokens=100,
        messages=[{
            "role": "user",
            "content": f"""Score 0.0 to 1.0: Does this answer address the question?
            1.0 = directly answers, 0.0 = completely off-topic.
            Question: {question}
            Answer: {answer}
            Reply with ONLY a JSON object: {{"score": <number>}}"""
        }],
    )
    try:
        return json.loads(response.content[0].text)["score"]
    except:
        return 0.5


def score_context_precision(question, context):
    """Was the retrieved context relevant to the question? (0.0 = irrelevant, 1.0 = perfect)"""
    response = client.messages.create(
        model="claude-sonnet-4-20250514",
        max_tokens=100,
        messages=[{
            "role": "user",
            "content": f"""Score 0.0 to 1.0: Does this context contain info to answer the question?
            1.0 = perfect context, 0.0 = completely irrelevant.
            Question: {question}
            Context: {context}
            Reply with ONLY a JSON object: {{"score": <number>}}"""
        }],
    )
    try:
        return json.loads(response.content[0].text)["score"]
    except:
        return 0.5
```

These functions send each test case to Claude and ask it to score the quality. This approach is called **LLM-as-judge** -- using one LLM to evaluate another.

Go back to your `main.py` chatbot from Lab 12-A. Add response caching so repeated questions do not cost money.

```python
import hashlib
import time as time_module

class ResponseCache:
    """Cache chatbot answers for 1 hour to save API costs."""

    def __init__(self, ttl_seconds=3600):
        self.cache = {}  # key -> {response, timestamp}
        self.ttl = ttl_seconds
        self.hits = 0    # how many times cache was used
        self.misses = 0  # how many times LLM was called

    def _key(self, question):
        return hashlib.md5(question.strip().lower().encode()).hexdigest()

    def get(self, question):
        key = self._key(question)
        entry = self.cache.get(key)
        if entry and time_module.time() - entry["ts"] < self.ttl:
            self.hits += 1
            return entry["response"]
        self.misses += 1
        return None

    def set(self, question, response):
        self.cache[self._key(question)] = {"response": response, "ts": time_module.time()}

cache = ResponseCache(ttl_seconds=3600)
```

